// Error handling wrapper
try {
  // Merge commits from both pages
  const commitsPage1 = $('Get Commits Page 1').all()[0]?.json || [];
  const commitsPage2 = $('Get Commits Page 2').all()[0]?.json || [];
  const commits = [...(Array.isArray(commitsPage1) ? commitsPage1 : []), ...(Array.isArray(commitsPage2) ? commitsPage2 : [])];

  const issues = $('Get Issues').all()[0]?.json || [];
  const prs = $('Get PRs').all()[0]?.json || [];

  // Filter merged PRs
  const mergedPRs = Array.isArray(prs) ? prs.filter(p => p.merged_at) : [];

  // Limit to prevent token overflow (max 50 items each)
  const MAX_ITEMS = 50;

  // Generate unique run ID for idempotency
  const runId = $now.toISO();

  return [{
    json: {
      runId: runId,
      week: $now.minus({days: 7}).toISODate() + ' to ' + $now.toISODate(),
      repo: $env.GITHUB_REPO,
      language: $env.LANGUAGE || 'EN',
      timezone: $env.TIMEZONE || 'UTC',
      stats: {
        commits: Array.isArray(commits) ? commits.length : 0,
        issuesClosed: Array.isArray(issues) ? issues.length : 0,
        prsMerged: mergedPRs.length,
        truncated: (commits.length > MAX_ITEMS || issues.length > MAX_ITEMS || mergedPRs.length > MAX_ITEMS)
      },
      // Sample data to prevent token overflow
      commits: Array.isArray(commits) ? commits.slice(0, MAX_ITEMS).map(c => ({
        message: c.commit?.message?.split('\n')[0],
        author: c.commit?.author?.name,
        sha: c.sha?.substring(0, 7),
        date: c.commit?.author?.date
      })) : [],
      issues: Array.isArray(issues) ? issues.slice(0, MAX_ITEMS).map(i => ({
        title: i.title,
        number: i.number,
        labels: i.labels?.map(l => l.name) || [],
        closedAt: i.closed_at
      })) : [],
      prs: mergedPRs.slice(0, MAX_ITEMS).map(p => ({
        title: p.title,
        number: p.number,
        author: p.user?.login,
        mergedAt: p.merged_at
      })),
      error: null
    }
  }];
} catch (error) {
  // Return error state instead of failing
  return [{
    json: {
      runId: $now.toISO(),
      week: $now.minus({days: 7}).toISODate() + ' to ' + $now.toISODate(),
      repo: $env.GITHUB_REPO,
      language: $env.LANGUAGE || 'EN',
      stats: { commits: 0, issuesClosed: 0, prsMerged: 0, truncated: false },
      commits: [],
      issues: [],
      prs: [],
      error: error.message || 'Unknown error in data processing'
    }
  }];
}

// Check for errors and skip if Claude failed
const claudeOutput = $input.all()[0]?.json;
const processData = $('Process Data (With Error Handling)').all()[0]?.json;

if (!claudeOutput || claudeOutput.error || processData?.error) {
  // Send error notification instead
  return [{
    json: {
      skip: true,
      error: claudeOutput?.error || processData?.error || 'Claude API call failed',
      runId: processData?.runId
    }
  }];
}

// Extract summary from Claude response
const summary = claudeOutput.content?.[0]?.text || 'Failed to generate summary';

return [{
  json: {
    runId: processData.runId,
    summary: summary,
    week: processData.week,
    repo: processData.repo
  }
}];
